// toPermissionTreeDTO 递归转换权限树。
func toPermissionTreeDTO(nodes []*appPermissionNode) []*PermissionTreeDTO {
	out := make([]*PermissionTreeDTO, 0, len(nodes))
	for _, node := range nodes {
		dto := &PermissionTreeDTO{PermissionDTO: *toPermissionDTO(node.Entry)}
		dto.Children = toPermissionTreeDTO(node.Children)
		out = append(out, dto)
	}
	return out
}

// appPermissionNode 是 app.PermissionNode 的结构别名，避免 dto 依赖 app 内部类型名。
type appPermissionNode = struct {
	Entry    catalog.Entry
	Children []*appPermissionNode
}
